('round-bar', 'Round Bar', 'bar', 'round_bar', 'piece', 'bar', 0, array[3000, 6000]::numeric[], '[]'::jsonb, '[{"key":"d","label":"Diameter","unit":"mm","std":[6,8,10,12,16,20,25,32,40,50,63,75,100,125,150,200],"min":3,"max":600}]'::jsonb, 'Solid bright or black round bars for turning, shafts, pins and general machining.', 1),
