insert into public.rm_materials (slug, name, short_name, density, hsn_codes, gst_rate, description, sort_order) values
('stainless-steel', 'Stainless Steel', 'SS', 7.93, '{"bar":"7222","flat":"7219","section":"7222","seamless":"7304","welded":"7306","wire":"7221"}'::jsonb, 18, 'Corrosion-resistant iron–chromium(–nickel) steels. Austenitic grades (304, 316) are non-magnetic and weldable; martensitic grades (410, 420, 440C) harden; duplex grades combine strength with chloride resistance.', 1),
('mild-steel', 'Mild Steel', 'MS', 7.85, '{"bar":"7214","flat":"7208","section":"7216","seamless":"7304","welded":"7306","wire":"7213"}'::jsonb, 18, 'Low-carbon structural steel — weldable, easy to fabricate and the most economical choice for frames, sections and plates.', 2),
('carbon-steel', 'Carbon Steel', 'CS', 7.85, '{"bar":"7214","flat":"7208","section":"7216","seamless":"7304","welded":"7306","wire":"7213"}'::jsonb, 18, 'Medium-carbon engineering steels for shafts, gears and machined parts; can be hardened and tempered.', 3),
('alloy-steel', 'Alloy Steel', 'AS', 7.85, '{"bar":"7228","flat":"7225","section":"7228","seamless":"7304","welded":"7306","wire":"7227"}'::jsonb, 18, 'Chromium, nickel and molybdenum alloyed steels (EN series) for high-strength, tough or case-hardened components.', 4),
('tool-steel', 'Tool Steel', 'TS', 7.75, '{"bar":"7228","flat":"7225","section":"7228","seamless":"7304","welded":"7306","wire":"7227"}'::jsonb, 18, 'High-carbon alloy steels for dies, punches, moulds and cutting tools; supplied annealed for machining.', 5),
('spring-steel', 'Spring Steel', 'SPR', 7.85, '{"bar":"7228","flat":"7225","section":"7228","seamless":"7304","welded":"7306","wire":"7227"}'::jsonb, 18, 'High-carbon and chrome-vanadium steels that return to shape after load — springs, clips, blades.', 6),
('aluminium', 'Aluminium', 'Al', 2.7, '{"bar":"7604","flat":"7606","section":"7604","seamless":"7608","welded":"7608","wire":"7605"}'::jsonb, 18, 'Light (about one-third the weight of steel), corrosion-resistant and highly machinable. Series 5xxx for marine/sheet work, 6xxx for extrusions and general machining, 2xxx/7xxx for high strength.', 7),
('copper', 'Copper', 'Cu', 8.94, '{"bar":"7407","flat":"7409","section":"7407","seamless":"7411","welded":"7411","wire":"7408"}'::jsonb, 18, 'Best-in-class electrical and thermal conductivity — busbars, earthing, heat exchangers and plumbing.', 8),
('brass', 'Brass', 'Brass', 8.5, '{"bar":"7407","flat":"7409","section":"7407","seamless":"7411","welded":"7411","wire":"7408"}'::jsonb, 18, 'Copper–zinc alloys: free-machining for turned parts and fittings, ductile grades for deep drawing and tubes.', 9),
('bronze', 'Bronze', 'Bronze', 8.8, '{"bar":"7407","flat":"7409","section":"7407","seamless":"7411","welded":"7411","wire":"7408"}'::jsonb, 18, 'Copper–tin and copper–aluminium alloys for bushes, bearings, gears and marine hardware.', 10),
('nickel-alloys', 'Nickel Alloys', 'Ni', 8.4, '{"bar":"7505","flat":"7506","section":"7505","seamless":"7507","welded":"7507","wire":"7505"}'::jsonb, 18, 'Nickel-based superalloys for extreme corrosion and temperature — chemical plant, oil & gas, aerospace.', 11),
('titanium', 'Titanium', 'Ti', 4.51, '{"bar":"8108","flat":"8108","section":"8108","seamless":"8108","welded":"8108","wire":"8108"}'::jsonb, 18, 'Very high strength-to-weight and outstanding corrosion resistance — aerospace, medical and chemical service.', 12)
on conflict (slug) do update set name = excluded.name, short_name = excluded.short_name, density = excluded.density,
  hsn_codes = excluded.hsn_codes, description = excluded.description, sort_order = excluded.sort_order;

