insert into public.rm_grades (material_id, slug, name, equivalents, description, applications, density, shape_slugs, sort_order)
select m.id, g.slug, g.name, g.equivalents, g.description, g.applications, g.density, g.shape_slugs, g.sort_order
from _rm_seed_grades g join public.rm_materials m on m.slug = g.material
on conflict (material_id, slug) do update set name = excluded.name, equivalents = excluded.equivalents,
  description = excluded.description, applications = excluded.applications, density = excluded.density,
  shape_slugs = excluded.shape_slugs, sort_order = excluded.sort_order;

insert into public.rm_rates (grade_id, shape_id, rate_per_kg)
select rg.id, null, g.rate
from _rm_seed_grades g
join public.rm_materials m on m.slug = g.material
join public.rm_grades rg on rg.material_id = m.id and rg.slug = g.slug
where not exists (select 1 from public.rm_rates r where r.grade_id = rg.id and r.shape_id is null);

drop table if exists _rm_seed_grades;
